function doSearch(q,scope){var ex=expandQuery(q),out=[],types=detectTypes(q),pred=PRED.analyzePredictive(q);if(types.length&&(scope==="all"||scope==="type"))types.slice(0,8).forEach(function(t){out.push({d:{g:"type",id:"type-"+t.id,title:t.label,sub:"🧩 Type de panne · "+typeLinked([t]).length+" fiche(s) liée(s)",body:"",keys:"",ref:t},sc:96});});if(pred.vehicle&&(scope==="all"||scope==="vehicle"))out.push({d:{g:"vehicle",id:"veh",title:[pred.vehicle.brand,pred.vehicle.model,pred.vehicle.engine,pred.vehicle.power?pred.vehicle.power+"ch":""].filter(Boolean).join(" "),sub:"🚗 Véhicule détecté · "+(pred.vehicle.years||"—")+" · confiance "+pred.vehicle.confidence,body:"",keys:"",ref:pred.vehicle},sc:100});if(scope==="all"||scope==="corr"){(PRED.getCorrelations?PRED.getCorrelations():[]).forEach(function(c){var sc=0,hay=norm([c.brand,c.model,c.engine,c.failure,c.description].join(" "));if(types.length&&types.some(function(t){return(t.systems||[]).indexOf(c.system)>=0;}))sc+=70;ex.terms.forEach(function(t){if(hay.indexOf(t)>=0)sc+=12;});if(pred.vehicle&&norm(pred.vehicle.brand||"")===norm(c.brand)&&norm(pred.vehicle.model||"")===norm(c.model))sc+=40;if(sc>0)out.push({d:{g:"corr",id:"corr-"+hashStr(c.brand+c.model+c.engine+c.failure),title:[c.brand,c.model,c.engine].filter(Boolean).join(" ")+" — "+c.failure,sub:"🔗 Corrélation · "+c.probability+"/10 · "+sysLabel(c.system),body:c.description||"",keys:"",ref:{failure:[c.brand,c.model,c.engine,c.failure].filter(Boolean).join(" ")}},sc:sc});});}if(scope==="all"||scope==="vehicle"){var qn=norm(q);PRED.getModels().forEach(function(m){if(qn.indexOf(norm(m.name))>=0||(m.aliases||[]).some(function(a){return qn.indexOf(norm(a))>=0;}))out.push({d:{g:"vehicle",id:"mod-"+hashStr(m.brand+m.name),title:m.brand+" "+m.name,sub:"🚗 Modèle · "+(m.years||"")+" · "+(m.variants||[]).length+" motorisations",body:"",keys:"",ref:{brand:m.brand,model:m.name}},sc:80});});PRED.getEngines().forEach(function(en){var hay=norm(en.code+" "+(en.names||[]).join(" ")),sc=0;ex.terms.forEach(function(t){if(hay.indexOf(t)>=0)sc+=40;});if(types.length&&(en.knownIssues||[]).some(function(k){var kn=norm(k);return types.some(function(t){return t.kw.some(function(kk){var k2=norm(kk);return kn.indexOf(k2)>=0||k2.indexOf(kn)>=0;});});}))sc+=30;if(sc>0)out.push({d:{g:"vehicle",id:"eng-"+hashStr(en.code),title:en.code+" ("+((en.names||[])[0]||"")+")",sub:"🛠️ Motorisation · "+(en.knownIssues||[]).join(", "),body:"",keys:"",ref:{engine:en.code,brand:""}},sc:sc});});}INDEX.forEach(function(d){if(scope!=="all"&&d.g!==scope&&!(scope==="type"&&d.g==="record"))return;var sc=0,h=0,ti=norm(d.title),bo=norm(d.body),ke=norm(d.keys);ex.terms.forEach(function(t){if(ti.indexOf(t)>=0){sc+=14;h++;}else if(ke.indexOf(t)>=0){sc+=10;h++;}else if(bo.indexOf(t)>=0){sc+=5;h++;}});if(types.length&&d.g==="record"){var linked=types.some(function(ty){return(ty.systems&&ty.systems.indexOf(d.ref.system)>=0)||ty.kw.some(function(k){return bo.indexOf(norm(k))>=0;});});if(linked){sc+=20;h++;}}if(d.g==="record")sc+=8;if(h)out.push({d:d,sc:sc});});out.sort(function(a,b){return b.sc-a.sc;});return{ex:ex,hits:out.slice(0,200)};}
function renderSearch(){var q=gv("q").trim(),scope=gv("qScope")||"all";if(q.length<2){html("results","");html("chips",'<span class="chip muted">Peugeot · 3008 · 5008 · BMW N47 · THP · chaîne · courroie · batterie · turbo · FAP · ADAS · tablette</span>');currentHits=[];active=-1;return;}var r=doSearch(q,scope);currentHits=r.hits;active=r.hits.length?0:-1;html("chips",r.ex.chips.map(function(c){return '<button class="chip" data-chip="'+esc(c)+'">'+esc(c)+'</button>';}).join(""));var groups={type:"🧩 Types de panne",vehicle:"🚗 Véhicules / motorisations",corr:"🔗 Corrélations prédictives",record:"Pannes connues",dtc:"DTC",method:"Méthode",ref:"Veille"},out="",last="";if(!r.hits.length)out='<div class="empty">Aucun résultat.</div>';r.hits.forEach(function(h,i){if(h.d.g!==last){last=h.d.g;out+='<div class="result-group">'+groups[h.d.g]+' · '+r.hits.filter(function(x){return x.d.g===h.d.g;}).length+'</div>';}out+='<div class="result'+(i===active?' active':'')+'" data-i="'+i+'"><div><b>'+esc(h.d.title)+'</b><small>'+esc(h.d.sub)+'</small></div><span class="tag">'+Math.round(h.sc)+'</span></div>';});html("results",out);}
function openResult(h){var d=h.d;if(d.g==="type")runAnalysis(d.ref.query||d.ref.kw.slice(0,2).join(" "));else if(d.g==="vehicle")runAnalysis([d.ref.brand,d.ref.model,d.ref.engine].filter(Boolean).join(" ")||d.title);else if(d.g==="corr")runAnalysis(d.ref.failure);else if(d.g==="record")runAnalysis((d.ref.keywords&&d.ref.keywords[0])||d.ref.title);else if(d.g==="dtc")openDrawer("DTC",d.title,'<p>'+esc(d.ref.txt)+'</p>',[{label:"Analyser",fn:function(){closeDrawer();runAnalysis(d.ref.q);}}]);else if(d.g==="ref"){var u=safeUrl(d.ref.url);if(u!=="#")W.open(u,"_blank","noopener");}else openDrawer("Méthode",d.title,'<p>'+esc(d.ref[1])+'</p>',[]);}
