function filteredKB(){var s=libState(),list=KB.slice();if(s.q){var terms=expandQuery(s.q).terms;list=list.map(function(e){var sc=0,ti=norm(e.title),bo=norm(recordBody(e));terms.forEach(function(t){if(ti.indexOf(t)>=0)sc+=14;else if(bo.indexOf(t)>=0)sc+=5;});return{e:e,sc:sc};}).filter(function(x){return x.sc>0;}).sort(function(a,b){return b.sc-a.sc;}).map(function(x){return x.e;});}if(s.brand)list=list.filter(function(e){return recVeh(e).indexOf(norm(s.brand))>=0;});if(s.model)list=list.filter(function(e){return recVeh(e).indexOf(norm(s.model))>=0;});if(s.engine)list=list.filter(function(e){return recVeh(e).indexOf(norm(s.engine))>=0;});if(s.power)list=list.filter(function(e){return recVeh(e).indexOf(norm(s.power))>=0||recVeh(e).indexOf(norm(s.engine))>=0;});if(s.system)list=list.filter(function(e){return e.system===s.system;});if(s.energy)list=list.filter(function(e){return e.energy===s.energy;});if(s.severity)list=list.filter(function(e){return e.severity===s.severity;});if(s.source==="local")list=list.filter(function(e){return!e.imported;});if(s.source==="imported")list=list.filter(function(e){return e.imported;});if(s.sort==="az")list.sort(function(a,b){return a.title.localeCompare(b.title,"fr");});else if(s.sort==="severity")list.sort(function(a,b){return sevRank(b.severity)-sevRank(a.severity);});else if(s.sort==="recent")list.sort(function(a,b){return(b.importedAt||0)-(a.importedAt||0);});return list;}
