function openRecordDrawer(e){openDrawer("Fiche "+(e.imported?"importée":"locale"),e.title,'<p><b>Origine :</b> '+esc(e.origin)+'</p><p><b>Mécanisme :</b> '+esc(e.mechanism)+'</p><p><b>Conséquences :</b></p><ul>'+listify(e.consequences).map(function(x){return'<li>'+esc(x)+'</li>';}).join("")+'</ul><p><b>Véhicules :</b> '+esc(listify(e.engines).join(", ")||"—")+'</p>',[{label:"Analyser",fn:function(){closeDrawer();runAnalysis((e.keywords&&e.keywords[0])||e.title);}},{label:"Présenter",fn:function(){closeDrawer();openRecordDeck([e],e.id);}}]);}
function openEditor(e){if(!EIK.admin)return;txt("editorTitle",e?"Modifier":"Nouvelle fiche");sv("f_id",e?e.id:"");sv("f_title",e?e.title:"");sv("f_system",e?e.system:SYSTEMS[0].id);sv("f_energy",e?e.energy:"Thermique");sv("f_zone",e?e.zone:"");sv("f_severity",e?e.severity:"Élevé");sv("f_keywords",e?(e.keywords||[]).join(", "):"");sv("f_engines",e?(e.engines||[]).join("\n"):"");sv("f_origin",e?e.origin:"");sv("f_mechanism",e?e.mechanism:"");sv("f_roots",e?(e.roots||[]).join("\n"):"");sv("f_consequences",e?(e.consequences||[]).join("\n"):"");sv("f_symptoms",e?(e.symptoms||[]).join("\n"):"");sv("f_dtc",e?(e.dtc||[]).join(", "):"");sv("f_evidence",e?(e.evidence||[]).join("\n"):"");sv("f_tests",e?(e.tests||[]).join("\n"):"");sv("f_actions",e?(e.actions||[]).join("\n"):"");sv("f_safety",e?(e.safety||[]).join("\n"):"");sv("f_legal",e?e.legal:"");sv("f_sources",e?(e.sources||[]).map(function(s){return s.label+" | "+s.url;}).join("\n"):"");var ed=byId("editor");if(ed)ed.hidden=false;}
function saveRecord(){var id=gv("f_id")||uid(),sources=lines(gv("f_sources")).map(function(l){var p=l.split("|");return{label:(p[0]||"Source").trim(),url:(p[1]||"").trim()};}).filter(function(s){return /^https?:\/\//.test(s.url);});var rec={id:id,title:gv("f_title").trim(),system:gv("f_system"),energy:gv("f_energy"),zone:gv("f_zone").trim(),severity:gv("f_severity"),priority:80,keywords:csv(gv("f_keywords")),engines:lines(gv("f_engines")),origin:gv("f_origin").trim(),mechanism:gv("f_mechanism").trim(),roots:lines(gv("f_roots")),consequences:lines(gv("f_consequences")),symptoms:lines(gv("f_symptoms")),dtc:csv(gv("f_dtc")),evidence:lines(gv("f_evidence")),tests:lines(gv("f_tests")),actions:lines(gv("f_actions")),safety:lines(gv("f_safety")),legal:gv("f_legal").trim(),sources:sources,related:[],updated:new Date().toISOString()};if(!rec.title||!rec.origin||!rec.mechanism){toast("Champs requis manquants");return;}local.overrides[id]=rec;delete local.deleted[id];store("eik-local",local);refreshKB();var ed=byId("editor");if(ed)ed.hidden=true;EIK.log("Édition fiche",true,rec.title);}
function deleteRecords(ids){if(!EIK.admin||!ids.length)return;undoStack.push(JSON.stringify(local));ids.forEach(function(id){var r=KB.find(function(e){return e.id===id;});if(r)local.deleted[id]=r;delete local.overrides[id];delete selected[id];});store("eik-local",local);refreshKB();toast("Supprimé — Annuler disponible","undo");}
function undo(){var b=undoStack.pop();if(!b)return;local=JSON.parse(b);store("eik-local",local);refreshKB();toast("Suppression annulée");}
function importJSON(f){var fr=new FileReader();fr.onload=function(){try{var arr=JSON.parse(fr.result);if(!Array.isArray(arr))throw 0;var n=0;arr.forEach(function(e){if(e&&e.id&&e.title&&e.origin&&e.mechanism){local.overrides[e.id]=e;delete local.deleted[e.id];n++;}});store("eik-local",local);refreshKB();toast(n+" fiche(s) importée(s)");}catch(e){toast("JSON invalide");}};fr.readAsText(f);}
function recordSlides(e){return[{h:e.title,cover:true,sub:e.zone},{h:"Origine",b:e.origin},{h:"Mécanisme",b:e.mechanism},{h:"Causes",l:e.roots},{h:"Conséquences",l:e.consequences},{h:"Symptômes",l:e.symptoms},{h:"DTC",l:e.dtc},{h:"Preuves",l:e.evidence},{h:"Tests",l:e.tests},{h:"Actions",l:e.actions},{h:"Sécurité",l:e.safety},{h:"Juridique",b:e.legal},{h:"Sources",src:e.sources||[]}];}
function analysisSlides(a){var s=recordSlides({title:a.title,zone:a.systemLabel,origin:a.origin,mechanism:a.mechanism,roots:a.roots,consequences:a.consequences,symptoms:a.symptoms,dtc:a.dtc,evidence:a.evidence,tests:a.tests,actions:a.actions,safety:a.safety,legal:a.legal,sources:a.sources,energy:a.energy});if(a.vehicleDesc)s.splice(1,0,{h:"Véhicule détecté",b:a.vehicleDesc});if(a.typeLabel)s.splice(1,0,{h:"Type de panne",b:a.typeLabel});return s;}
function openRecordDeck(list,startId){deckChapters=list.map(function(e){return{title:e.title,en:e.energy,slides:recordSlides(e)};});deckIdx=Math.max(0,list.findIndex(function(e){return e.id===startId;}));slideIdx=0;var dk=byId("deck");if(dk)dk.hidden=false;D.body.classList.add("locked");renderSlide();}
function openAnalysisDeck(a){deckChapters=[{title:a.title,en:a.energy,slides:analysisSlides(a)}];deckIdx=0;slideIdx=0;var dk=byId("deck");if(dk)dk.hidden=false;D.body.classList.add("locked");renderSlide();}
